<?php require_once __DIR__.'/config/config.php';if(isset($_GET['logout'])){unset($_SESSION['member_id']);header('Location: member-login.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf($_POST['csrf_token']??'')){$err='Invalid request';}else{$q=$pdo->prepare("SELECT * FROM members WHERE member_code=? AND status='active' LIMIT 1");$q->execute([trim($_POST['member_code']??'')]);$m=$q->fetch();if($m&&password_verify($_POST['password']??'',$m['password'])){session_regenerate_id(true);$_SESSION['member_id']=$m['id'];header('Location: member-login.php?welcome=1');exit;}else{$err='Invalid member code or password. Contact the cooperative office if you need assistance.';}}}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="assets/css/style.css"><title>Member Login</title><?= favicon_tags() ?><?= theme_head_tags() ?></head><body class="admin"><form class="loginForm" method="post"><h2><?=tr('Member Portal','सदस्य पोर्टल')?></h2><?php if($err):?><p style="color:#b42318"><?=e($err)?></p><?php endif;?><?php if(isset($_GET['welcome'])&&isset($_SESSION['member_id'])): $q=$pdo->prepare("SELECT full_name_en,full_name_ne,member_code,share_count,share_amount FROM members WHERE id=?");$q->execute([$_SESSION['member_id']]);$m=$q->fetch();?><h3><?=e($current_lang==='ne'?$m['full_name_ne']:$m['full_name_en'])?></h3><p>Member ID: <?=e($m['member_code'])?></p><p>Shares: <?=e($m['share_count'])?></p><p>Share capital: <?=e(format_money((float)$m['share_amount'],$current_lang))?></p><a href="member-login.php?logout=1">Logout</a><?php else:?><?=csrf_field()?><input name="member_code" placeholder="<?=tr('Member Code','सदस्य कोड')?>" required><input type="password" name="password" placeholder="<?=tr('Password','पासवर्ड')?>" required><button class="btn"><?=tr('Sign In','लगइन')?></button><?php endif;?><a href="index.php">← <?=tr('Back to website','वेबसाइटमा फर्कनुहोस्')?></a></form></body></html><?php if(isset($_GET['logout'])){unset($_SESSION['member_id']);header('Location: member-login.php');}